it('calls onLoadMore when the sentinel intersects the viewport', () => {
  let intersectionCallback: IntersectionObserverCallback = () => {};
  class MockIntersectionObserver {
    constructor(cb: IntersectionObserverCallback) { intersectionCallback = cb; }
    observe() {}
    unobserve() {}
    disconnect() {}
  }
  // @ts-expect-error test stub
  window.IntersectionObserver = MockIntersectionObserver;

  const onLoadMore = vi.fn();
  render(<InfiniteScrollList items={[1, 2, 3]} renderItem={(n: number) => <div key={n}>{n}</div>} onLoadMore={onLoadMore} />);
  intersectionCallback([{ isIntersecting: true } as IntersectionObserverEntry], {} as IntersectionObserver);
  expect(onLoadMore).toHaveBeenCalledTimes(1);
});

