it('logs every action before dispatching it', () => {
  const spy = vi.spyOn(console, 'log').mockImplementation(() => {});
  const reducer = (state: number, _action: { type: 'inc' }) => state + 1;
  const { result } = renderHook(() => useLocalReducer(reducer, 0));
  act(() => result.current.dispatchLogged({ type: 'inc' }));
  expect(result.current.state).toBe(1);
  expect(spy).toHaveBeenCalledWith({ type: 'inc' });
  spy.mockRestore();
});

