// NOTE: jsdom cannot evaluate the :focus-visible pseudo-class or computed CSS outline
// reliably -- this one must run in a real browser via Playwright, not RTL/jsdom.
import { test, expect } from '@playwright/test';

test('shows a focus-visible outline on keyboard focus but not on mouse click', async ({ page }) => {
  await page.goto('/storybook/iframe.html?id=button--default');
  const button = page.getByRole('button', { name: 'Submit' });

  await button.click();
  await expect(button).not.toHaveCSS('outline-style', 'solid');

  await page.keyboard.press('Tab');
  await expect(page.getByRole('button', { name: 'Submit' })).toHaveCSS('outline-style', 'solid');
});

