it('debounces the async validator call', () => {
  vi.useFakeTimers();
  const validateFn = vi.fn().mockResolvedValue(true);
  const { rerender } = renderHook(({ value }) => useAsyncValidation(value, validateFn), { initialProps: { value: 'a' } });
  rerender({ value: 'ay' });
  rerender({ value: 'ayu' });
  expect(validateFn).not.toHaveBeenCalled();
  act(() => { vi.advanceTimersByTime(400); });
  expect(validateFn).toHaveBeenCalledWith('ayu');
  vi.useRealTimers();
});

